value = re.sub(r'[_-]', '', value)
match = re.search(r'\b(\d{1,2}):(\d{2})\s*(A|P)\.M\.?\s*\b', value)
if match:
    hours, minutes, period = match.groups()
    if period.upper() == 'P':
        hours = str(int(hours) + 12)
    return "%s" % ({hours}:{minutes})
else:
    return value

